import '../../naming/name_converter.dart';
import '../../openapi/models.dart';
import '../shared/code_builders.dart';
import '../shared/field_spec.dart';

/// Emits Dart sources for a parsed OpenAPI document.
abstract final class ApiCodegen {
  static const generatedBanner =
      '// GENERATED CODE - DO NOT MODIFY BY HAND\n'
      '// Generated by Chico Flutter DevKit (`devkit generate api`).\n'
      '// Regenerate safely; keep custom code outside this folder.\n';

  static String modelsBarrel({
    required String clientPascal,
    required List<OpenApiSchema> schemas,
  }) {
    final exports =
        schemas
            .where((s) => s.kind != OpenApiSchemaKind.alias)
            .map((s) => NameConverter.parse(s.name).snakeCase)
            .toSet()
            .toList()
          ..sort();
    final buffer = StringBuffer(generatedBanner)
      ..writeln()
      ..writeln('/// Models for $clientPascal API client.')
      ..writeln('library;')
      ..writeln();
    for (final snake in exports) {
      buffer.writeln("export '$snake.dart';");
    }
    return buffer.toString();
  }

  static String modelFile(
    OpenApiSchema schema, {
    Set<String> enumTypeNames = const {},
    Set<String> knownModelNames = const {},
  }) {
    final className = NameConverter.parse(schema.name).pascalCase;
    final buffer = StringBuffer(generatedBanner)..writeln();

    if (schema.description != null && schema.description!.isNotEmpty) {
      buffer.writeln('/// ${schema.description}');
    }

    if (schema.kind == OpenApiSchemaKind.enumeration) {
      buffer.writeln('enum $className {');
      for (final value in schema.enumValues) {
        final name = NameConverter.parse(value).camelCase;
        buffer.writeln("  $name('$value'),");
      }
      buffer
        ..writeln('  ;')
        ..writeln()
        ..writeln('  const $className(this.wireValue);')
        ..writeln('  final String wireValue;')
        ..writeln()
        ..writeln('  static $className fromJson(Object? json) {')
        ..writeln('    final raw = json?.toString();')
        ..writeln('    return $className.values.firstWhere(')
        ..writeln('      (value) => value.wireValue == raw,')
        ..writeln(
          "      orElse: () => throw FormatException('Unknown $className: \$json'),",
        )
        ..writeln('    );')
        ..writeln('  }')
        ..writeln()
        ..writeln('  String toJson() => wireValue;')
        ..writeln('}');
      return buffer.toString();
    }

    if (schema.kind == OpenApiSchemaKind.alias) {
      buffer
        ..writeln('/// Type alias for OpenAPI schema `${schema.name}`.')
        ..writeln('typedef $className = ${schema.itemType ?? 'Object'};');
      return buffer.toString();
    }

    final fields = schema.fields
        .map(
          (f) => FieldSpec(
            name: f.name,
            type: f.dartType.replaceAll('?', ''),
            isNullable: f.dartType.endsWith('?') || !f.required,
          ),
        )
        .toList(growable: false);

    final imports = _modelImportsFor(
      fields: schema.fields,
      selfName: className,
      enumTypeNames: enumTypeNames,
      knownModelNames: knownModelNames,
    );
    for (final importPath in imports) {
      buffer.writeln("import '$importPath';");
    }
    if (imports.isNotEmpty) buffer.writeln();

    buffer
      ..writeln('/// Generated from OpenAPI schema `${schema.name}`.')
      ..writeln('class $className {')
      ..writeln(
        '  const $className(${CodeBuilders.constructorParams(fields)});',
      )
      ..writeln()
      ..writeln(CodeBuilders.fieldDeclarations(fields))
      ..writeln()
      ..writeln(_fromJsonWithKeys(className, schema.fields, enumTypeNames))
      ..writeln()
      ..writeln(_toJsonWithKeys(schema.fields, enumTypeNames))
      ..writeln()
      ..writeln(CodeBuilders.copyWithBody(className, fields))
      ..writeln()
      ..writeln(CodeBuilders.equality(className, fields))
      ..writeln()
      ..writeln(
        "  @override\n  String toString() => '$className(${fields.map((f) => '${f.name}: \$${f.name}').join(', ')})';",
      )
      ..writeln('}');
    return buffer.toString();
  }

  static String exceptionFile(String clientPascal) {
    return '''
$generatedBanner
/// HTTP / decoding failure thrown by [$clientPascal].
final class ${clientPascal}Exception implements Exception {
  const ${clientPascal}Exception({
    required this.message,
    this.statusCode,
    this.body,
    this.uri,
  });

  final String message;
  final int? statusCode;
  final String? body;
  final Uri? uri;

  @override
  String toString() {
    final code = statusCode == null ? '' : ' (\$statusCode)';
    return '${clientPascal}Exception\$code: \$message';
  }
}
''';
  }

  static String authFile({
    required String clientPascal,
    required OpenApiAuthConfig auth,
  }) {
    final buffer = StringBuffer(generatedBanner)
      ..writeln()
      ..writeln('/// Authentication configuration for [$clientPascal].')
      ..writeln('final class ${clientPascal}Auth {');

    switch (auth.type) {
      case OpenApiAuthType.none:
        buffer
          ..writeln('  const ${clientPascal}Auth();')
          ..writeln()
          ..writeln('  Map<String, String> headers() => const {};')
          ..writeln()
          ..writeln('  Map<String, String> queryParameters() => const {};');
      case OpenApiAuthType.bearer:
        buffer
          ..writeln('  const ${clientPascal}Auth({this.bearerToken});')
          ..writeln()
          ..writeln('  final String? bearerToken;')
          ..writeln()
          ..writeln('  Map<String, String> headers() {')
          ..writeln('    final token = bearerToken;')
          ..writeln('    if (token == null || token.isEmpty) return const {};')
          ..writeln("    return {'Authorization': 'Bearer \$token'};")
          ..writeln('  }')
          ..writeln()
          ..writeln('  Map<String, String> queryParameters() => const {};');
      case OpenApiAuthType.apiKey:
        final header = auth.headerName;
        final query = auth.queryName;
        buffer
          ..writeln('  const ${clientPascal}Auth({this.apiKey});')
          ..writeln()
          ..writeln('  final String? apiKey;')
          ..writeln()
          ..writeln('  Map<String, String> headers() {');
        if (header != null) {
          buffer
            ..writeln('    final key = apiKey;')
            ..writeln('    if (key == null || key.isEmpty) return const {};')
            ..writeln("    return {'$header': key};");
        } else {
          buffer.writeln('    return const {};');
        }
        buffer
          ..writeln('  }')
          ..writeln()
          ..writeln('  Map<String, String> queryParameters() {');
        if (query != null) {
          buffer
            ..writeln('    final key = apiKey;')
            ..writeln('    if (key == null || key.isEmpty) return const {};')
            ..writeln("    return {'$query': key};");
        } else {
          buffer.writeln('    return const {};');
        }
        buffer.writeln('  }');
    }

    buffer.writeln('}');
    return buffer.toString();
  }

  static String clientFile({
    required String clientPascal,
    required OpenApiDocument document,
  }) {
    final hasModels = document.schemas.values.any(
      (s) => s.kind != OpenApiSchemaKind.alias,
    );
    final defaultBase = document.defaultServer ?? 'http://localhost';
    final buffer = StringBuffer(generatedBanner)
      ..writeln()
      ..writeln("import 'dart:convert';")
      ..writeln("import 'dart:io';")
      ..writeln()
      ..writeln("import 'auth.dart';")
      ..writeln("import 'exception.dart';");
    if (hasModels) {
      buffer.writeln("import 'models/models.dart';");
    }
    buffer
      ..writeln()
      ..writeln('/// Generated API client for `${document.title}`.')
      ..writeln('///')
      ..writeln(
        '/// OpenAPI ${document.openApiVersion} · API ${document.version}',
      )
      ..writeln('final class $clientPascal {')
      ..writeln('  $clientPascal({')
      ..writeln('    String? baseUrl,')
      ..writeln('    ${clientPascal}Auth? auth,')
      ..writeln('    HttpClient? httpClient,')
      ..writeln(
        "  }) : baseUrl = _normalizeBaseUrl(baseUrl ?? '${_escapeDartString(defaultBase)}'),",
      )
      ..writeln('       auth = auth ?? const ${clientPascal}Auth(),')
      ..writeln('       _httpClient = httpClient ?? HttpClient();')
      ..writeln()
      ..writeln('  final String baseUrl;')
      ..writeln('  final ${clientPascal}Auth auth;')
      ..writeln('  final HttpClient _httpClient;')
      ..writeln()
      ..writeln('  void close() => _httpClient.close(force: false);')
      ..writeln();

    for (final op in document.operations) {
      buffer
        ..writeln(_operationMethod(clientPascal, op))
        ..writeln();
    }

    buffer
      ..writeln(_helpers(clientPascal))
      ..writeln('}');

    return buffer.toString();
  }

  static String readme({
    required String clientPascal,
    required String clientSnake,
    required OpenApiDocument document,
  }) {
    return '''
# $clientPascal

Generated from OpenAPI `${document.title}` (${document.openApiVersion}).

## Layout

- `generated/` — regenerated by `devkit generate api` (do not edit)
- Keep wrappers, interceptors, and hand-written adapters **outside** `generated/`

## Usage

```dart
final client = $clientPascal(
  baseUrl: '${document.defaultServer ?? 'https://api.example.com'}',
);

 // call generated methods, then:
client.close();
```

Regenerate:

```bash
devkit generate api $clientSnake --spec path/to/openapi.yaml --force
```
''';
  }

  static String _operationMethod(String clientPascal, OpenApiOperation op) {
    final params = <String>[];
    for (final parameter in op.parameters) {
      if (parameter.required) {
        params.add('required ${parameter.dartType} ${parameter.name}');
      } else {
        params.add('${parameter.dartType} ${parameter.name}');
      }
    }
    if (op.requestBodyType != null) {
      final bodyType = op.requestBodyType!;
      params.add(
        bodyType.endsWith('?') ? '$bodyType body' : 'required $bodyType body',
      );
    }

    final returnType = op.successResponseType ?? 'void';
    final futureType = returnType == 'void'
        ? 'Future<void>'
        : 'Future<$returnType>';
    final docs = StringBuffer('  /// ');
    if (op.summary != null && op.summary!.trim().isNotEmpty) {
      docs.writeln(op.summary!.trim());
      docs.writeln('  ///');
    }
    docs.writeln('  /// `${op.method.name.toUpperCase()} ${op.path}`');
    if (op.paginated) {
      docs.writeln(
        '  /// Pagination query parameters were detected for this operation.',
      );
    }

    final buffer = StringBuffer()
      ..write(docs)
      ..writeln('  $futureType ${op.methodName}({')
      ..writeln(params.map((p) => '    $p,').join('\n'))
      ..writeln('  }) async {')
      ..writeln("    var path = '${op.path}';");

    for (final parameter in op.parameters.where(
      (p) => p.location == OpenApiParameterLocation.path,
    )) {
      buffer.writeln(
        "    path = path.replaceAll('{${parameter.wireName}}', "
        'Uri.encodeComponent(${parameter.name}.toString()));',
      );
    }

    buffer.writeln('    final query = <String, String>{');
    buffer.writeln('      ...auth.queryParameters(),');
    for (final parameter in op.parameters.where(
      (p) => p.location == OpenApiParameterLocation.query,
    )) {
      if (parameter.required) {
        buffer.writeln(
          "      '${parameter.wireName}': ${parameter.name}.toString(),",
        );
      } else {
        buffer.writeln(
          '      if (${parameter.name} != null) '
          "'${parameter.wireName}': ${parameter.name}.toString(),",
        );
      }
    }
    buffer.writeln('    };');

    buffer.writeln('    final headers = <String, String>{');
    buffer.writeln("      'Accept': 'application/json',");
    buffer.writeln('      ...auth.headers(),');
    for (final parameter in op.parameters.where(
      (p) => p.location == OpenApiParameterLocation.header,
    )) {
      if (parameter.required) {
        buffer.writeln(
          "      '${parameter.wireName}': ${parameter.name}.toString(),",
        );
      } else {
        buffer.writeln(
          '      if (${parameter.name} != null) '
          "'${parameter.wireName}': ${parameter.name}.toString(),",
        );
      }
    }
    buffer.writeln('    };');

    if (op.requestBodyType != null) {
      buffer
        ..writeln("    headers['Content-Type'] = 'application/json';")
        ..writeln(
          '    final payload = ${_encodeBodyExpression(op.requestBodyType!)};',
        );
    } else {
      buffer.writeln('    const String? payload = null;');
    }

    buffer.writeln(
      "    final response = await _send('${op.method.name.toUpperCase()}', path, "
      'query: query, headers: headers, body: payload);',
    );
    buffer.writeln(_decodeReturn(clientPascal, returnType));
    buffer.writeln('  }');
    return buffer.toString();
  }

  static String _decodeReturn(String clientPascal, String returnType) {
    if (returnType == 'void') {
      return '    return;';
    }
    if (returnType == 'String') {
      return '    return response;';
    }
    if (returnType == 'Map<String, dynamic>') {
      return '''
    final decoded = jsonDecode(response);
    if (decoded is! Map<String, dynamic>) {
      throw ${clientPascal}Exception(
        message: 'Expected a JSON object response.',
        body: response,
      );
    }
    return decoded;''';
    }
    if (returnType.startsWith('List<')) {
      final inner = returnType.substring(5, returnType.length - 1);
      if (_isPrimitive(inner) || inner.startsWith('Map<')) {
        return '''
    final decoded = jsonDecode(response);
    if (decoded is! List) {
      throw ${clientPascal}Exception(
        message: 'Expected a JSON array response.',
        body: response,
      );
    }
    return decoded.cast<$inner>();''';
      }
      return '    return _decodeList(response, $inner.fromJson);';
    }
    if (_isPrimitive(returnType)) {
      return '''
    final decoded = jsonDecode(response);
    return decoded as $returnType;''';
    }
    // Enums use fromJson(Object?), models use fromJson(Map)
    return '''
    final decoded = jsonDecode(response);
    if (decoded is Map<String, dynamic>) {
      return $returnType.fromJson(decoded);
    }
    return $returnType.fromJson(decoded);''';
  }

  static bool _isPrimitive(String type) {
    return type == 'String' ||
        type == 'int' ||
        type == 'double' ||
        type == 'num' ||
        type == 'bool' ||
        type == 'Object';
  }

  static List<String> _modelImportsFor({
    required List<OpenApiField> fields,
    required String selfName,
    required Set<String> enumTypeNames,
    required Set<String> knownModelNames,
  }) {
    final names = <String>{};
    void consider(String type) {
      final clean = type.replaceAll('?', '');
      if (clean.startsWith('List<') && clean.endsWith('>')) {
        consider(clean.substring(5, clean.length - 1));
        return;
      }
      if (_isPrimitive(clean) ||
          clean.startsWith('Map<') ||
          clean == 'DateTime' ||
          clean == selfName) {
        return;
      }
      if (enumTypeNames.contains(clean) || knownModelNames.contains(clean)) {
        names.add(clean);
      }
    }

    for (final field in fields) {
      consider(field.dartType);
    }

    final imports =
        names
            .map((name) => '${NameConverter.parse(name).snakeCase}.dart')
            .toList()
          ..sort();
    return imports;
  }

  static String _encodeBodyExpression(String bodyType) {
    final clean = bodyType.replaceAll('?', '');
    if (_isPrimitive(clean) || clean.startsWith('Map<')) {
      return 'body == null ? null : jsonEncode(body)';
    }
    if (clean.startsWith('List<')) {
      final inner = clean.substring(5, clean.length - 1);
      if (_isPrimitive(inner) || inner.startsWith('Map<')) {
        return 'body == null ? null : jsonEncode(body)';
      }
      if (bodyType.endsWith('?')) {
        return 'body == null ? null : jsonEncode(body!.map((e) => e.toJson()).toList())';
      }
      return 'jsonEncode(body.map((e) => e.toJson()).toList())';
    }
    if (bodyType.endsWith('?')) {
      return 'body == null ? null : jsonEncode(body!.toJson())';
    }
    return 'jsonEncode(body.toJson())';
  }

  static String _fromJsonWithKeys(
    String className,
    List<OpenApiField> fields,
    Set<String> enumTypeNames,
  ) {
    final lines = fields.map((field) {
      final type = field.dartType.replaceAll('?', '');
      final nullable = field.dartType.endsWith('?') || !field.required;
      return '      ${field.name}: ${_decodeExpr("json['${field.jsonKey}']", type, nullable, enumTypeNames)},';
    });
    return '''
  factory $className.fromJson(Map<String, dynamic> json) {
    return $className(
${lines.join('\n')}
    );
  }''';
  }

  static String _toJsonWithKeys(
    List<OpenApiField> fields,
    Set<String> enumTypeNames,
  ) {
    final lines = fields.map((field) {
      final type = field.dartType.replaceAll('?', '');
      final nullable = field.dartType.endsWith('?') || !field.required;
      return "      '${field.jsonKey}': ${_encodeExpr(field.name, type, enumTypeNames, nullable: nullable)},";
    });
    return '''
  Map<String, dynamic> toJson() => {
${lines.join('\n')}
  };''';
  }

  static String _decodeExpr(
    String access,
    String type,
    bool nullable,
    Set<String> enumTypeNames,
  ) {
    if (_isPrimitive(type)) {
      return nullable ? '$access as $type?' : '$access as $type';
    }
    if (type == 'DateTime') {
      return nullable
          ? '$access == null ? null : DateTime.parse($access as String)'
          : 'DateTime.parse($access as String)';
    }
    if (type.startsWith('List<')) {
      final inner = type.substring(5, type.length - 1);
      final String mapExpr;
      if (_isPrimitive(inner) || inner.startsWith('Map<')) {
        mapExpr = 'e as $inner';
      } else if (enumTypeNames.contains(inner)) {
        mapExpr = '$inner.fromJson(e)';
      } else {
        mapExpr = '$inner.fromJson(e as Map<String, dynamic>)';
      }
      return nullable
          ? '($access as List<dynamic>?)?.map((e) => $mapExpr).toList()'
          : '($access as List<dynamic>).map((e) => $mapExpr).toList()';
    }
    if (type.startsWith('Map<')) {
      return nullable
          ? '$access as Map<String, dynamic>?'
          : '$access as Map<String, dynamic>';
    }
    if (enumTypeNames.contains(type)) {
      return nullable
          ? '$access == null ? null : $type.fromJson($access)'
          : '$type.fromJson($access)';
    }
    return nullable
        ? '$access == null ? null : $type.fromJson($access as Map<String, dynamic>)'
        : '$type.fromJson($access as Map<String, dynamic>)';
  }

  static String _encodeExpr(
    String name,
    String type,
    Set<String> enumTypeNames, {
    bool nullable = false,
  }) {
    if (type == 'DateTime') {
      return nullable ? '$name?.toIso8601String()' : '$name.toIso8601String()';
    }
    if (type.startsWith('List<')) {
      final inner = type.substring(5, type.length - 1);
      if (_isPrimitive(inner) || inner.startsWith('Map<')) return name;
      return nullable
          ? '$name?.map((e) => e.toJson()).toList()'
          : '$name.map((e) => e.toJson()).toList()';
    }
    if (_isPrimitive(type) || type.startsWith('Map<')) return name;
    return nullable ? '$name?.toJson()' : '$name.toJson()';
  }

  static String _escapeDartString(String value) {
    return value
        .replaceAll(r'\', r'\\')
        .replaceAll("'", r"\'")
        .replaceAll(r'$', r'\$');
  }

  static String _helpers(String clientPascal) {
    return '''
  static String _normalizeBaseUrl(String value) {
    return value.endsWith('/') ? value.substring(0, value.length - 1) : value;
  }

  Future<String> _send(
    String method,
    String path, {
    Map<String, String> query = const {},
    Map<String, String> headers = const {},
    String? body,
  }) async {
    final uri = Uri.parse('\$baseUrl\$path').replace(
      queryParameters: query.isEmpty ? null : query,
    );
    final request = await _httpClient.openUrl(method, uri);
    headers.forEach(request.headers.set);
    if (body != null) {
      request.add(utf8.encode(body));
    }
    final response = await request.close();
    final responseBody = await response.transform(utf8.decoder).join();
    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw ${clientPascal}Exception(
        message: 'Request failed',
        statusCode: response.statusCode,
        body: responseBody,
        uri: uri,
      );
    }
    return responseBody;
  }

  List<T> _decodeList<T>(
    String body,
    T Function(Map<String, dynamic> json) fromJson,
  ) {
    try {
      final decoded = jsonDecode(body);
      if (decoded is! List) {
        throw ${clientPascal}Exception(
          message: 'Expected a JSON array response.',
          body: body,
        );
      }
      return decoded
          .map((item) => fromJson(item as Map<String, dynamic>))
          .toList(growable: false);
    } on ${clientPascal}Exception {
      rethrow;
    } catch (error) {
      throw ${clientPascal}Exception(
        message: 'Failed to decode response list: \$error',
        body: body,
      );
    }
  }
''';
  }
}
